function selectSegment(i,focus=false){
 const s=segments[i];document.documentElement.style.setProperty('--segment',s.color);document.documentElement.style.setProperty('--segment-bg',s.bg);
 $$('.editorial-tabs button').forEach((b,n)=>{b.setAttribute('aria-selected',String(n===i));b.tabIndex=n===i?0:-1;if(n===i&&focus)b.focus();});
 $('#segment-panel').setAttribute('aria-labelledby',$$('.editorial-tabs button')[i].id);
 const icon=$('#segment-icon');icon.src=`assets/${s.icon}`;icon.alt=s.iconAlt;
 $('#segment-title').textContent=s.title;$('#segment-kicker').textContent=s.kicker;$('#segment-description').textContent=s.description;
 const makeList=(titles)=>titles.map(t=>{const li=document.createElement('li');li.textContent=t;return li;});
 $('#segment-topics').replaceChildren(...makeList(s.topics));
 $('#segment-infographics').replaceChildren(...makeList(s.infographics));
 $('#infographics-group').hidden=s.infographics.length===0;

}
$$('.editorial-tabs button').forEach((b,i)=>b.addEventListener('click',()=>selectSegment(i)));
function keyboardTabs(selector,fn){const tabs=$$(selector);tabs.forEach((t,i)=>t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i-1+tabs.length)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();fn(n);tabs[n].focus();}}));}
keyboardTabs('.editorial-tabs button',i=>selectSegment(i,true));
