const pagination=document.createElement('div');pagination.className='sample-pagination';pagination.innerHTML='<button id="gallery-prev" aria-label="Ver páginas anteriores">←</button><span id="gallery-position" aria-live="polite"></span><button id="gallery-next" aria-label="Ver más páginas">→</button>';$('#sample-grid').after(pagination);
function renderGallery(){
 const grid=$('#sample-grid');grid.replaceChildren();
 filtered.slice(galleryPage*4,galleryPage*4+4).forEach(p=>{const b=document.createElement('button');b.className='sample-card';b.setAttribute('aria-label',`Ampliar: ${p.title}`);b.innerHTML=`<div class="sample-image"><img src="${p.src||`assets/page-${p.page}.webp`}" alt="${p.title}, página real de Jach’a Puno" width="680" height="960" loading="lazy"><span class="sample-expand" aria-hidden="true">↗</span></div><div class="sample-meta"><h3>${p.title}</h3><span>${p.sheets?`${p.sheets.length} ${p.sheets.length===1?'página':'páginas'} · Completo`:p.filter==='cubiertas'?'Presentación':'Muestra'}</span></div><p class="sample-category">${p.category}${p.author?' · '+p.author:''}</p>`;b.addEventListener('click',()=>openPage(p.page));grid.append(b);});
 const total=Math.ceil(filtered.length/4);$('#sample-count').textContent=`${filtered.length} páginas en la selección`;$('#gallery-position').textContent=`${galleryPage+1} / ${total}`;$('#gallery-prev').disabled=galleryPage===0;$('#gallery-next').disabled=galleryPage===total-1;pagination.hidden=total<=1;
}
