function openModal(dialog){lastModalFocus=document.activeElement;dialog.showModal();document.body.classList.add('dialog-open');}
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{document.body.classList.remove('dialog-open');lastModalFocus?.focus();});$('.close-dialog',d).addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
const zoomButton=document.createElement('button');zoomButton.className='button subtle';zoomButton.id='viewer-zoom';zoomButton.textContent='Ampliar +';zoomButton.style.cssText='font-size:10px;padding:8px 12px;margin-left:auto';$('.viewer-top .close-dialog').before(zoomButton);
function renderViewer(){const p=viewerCollection[viewerIndex];$('#viewer-title').textContent=p.title;$('#viewer-image').src=p.src||`assets/page-${p.page}.webp`;$('#viewer-image').alt=`${p.title}. ${p.category}`;$('#viewer-position').textContent=`${viewerIndex+1} de ${viewerCollection.length}`;$('.viewer-prev').disabled=viewerIndex===0;$('.viewer-next').disabled=viewerIndex===viewerCollection.length-1;viewerZoom=false;applyZoom();}
function applyZoom(){const img=$('#viewer-image');img.style.maxHeight=viewerZoom?'none':'100%';img.style.width=viewerZoom?'100%':'auto';img.style.maxWidth='100%';$('#viewer-zoom').textContent=viewerZoom?'Ajustar −':'Ampliar +';$('#viewer-zoom').setAttribute('aria-pressed',String(viewerZoom));$('.viewer-stage').scrollTop=0;}
zoomButton.addEventListener('click',()=>{viewerZoom=!viewerZoom;applyZoom();});
function openPage(n){const article=articles.find(a=>a.page===String(n));if(article){viewerCollection=article.sheets;viewerIndex=0;renderViewer();openModal($('#page-dialog'));return;}viewerCollection=models.some(p=>p.page===String(n))?models:(filtered.some(p=>String(p.page)===String(n))?filtered:pages);viewerIndex=viewerCollection.findIndex(p=>String(p.page)===String(n));if(viewerIndex<0)return;renderViewer();openModal($('#page-dialog'));}
$$('[data-open-page]').forEach(b=>b.addEventListener('click',()=>openPage(b.dataset.openPage)));
$('.viewer-prev').addEventListener('click',()=>{if(viewerIndex>0){viewerIndex--;renderViewer();}});$('.viewer-next').addEventListener('click',()=>{if(viewerIndex<viewerCollection.length-1){viewerIndex++;renderViewer();}});
$('#page-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowRight'&&viewerIndex<viewerCollection.length-1){e.preventDefault();viewerIndex++;renderViewer();}if(e.key==='ArrowLeft'&&viewerIndex>0){e.preventDefault();viewerIndex--;renderViewer();}});
