let currentAd=0;
function renderAd(){
 const a=adOptions[currentAd];
 const visual=a.src?`<button class="ad-model-button" data-open-model="${a.model}" aria-label="Ampliar ${a.title.toLowerCase()}"><img class="ad-model" src="${a.src}" alt="${a.id==='completa'?'Ejemplo de anuncio de página completa del Museo Municipal Carlos Dreyer':a.id==='dos'?'Modelo de dos módulos unidos en el rectángulo superior':a.id==='tres'?'Modelo de tres módulos unidos en el rectángulo inferior':'Modelo de cinco espacios publicitarios individuales'}" width="1055" height="1491"><span>Ampliar modelo ↗</span></button>`:a.id==='especial'?`<div class="cover-space-preview"><img src="assets/portada.webp" alt="Portada de Jach’a Puno"><span>Ubicación por coordinar</span></div>`:`<div class="flap-diagram ${a.id==='contraportada'?'back-flap':''}" aria-label="Esquema del interior de tapa y su solapa"><div class="inside-cover">INTERIOR DE<br>${a.id==='portada'?'PORTADA':'CONTRAPORTADA'}<strong>JACH’A PUNO</strong></div><div class="inside-flap">SOLAPA</div></div>`;
 $('#support-panel').innerHTML=`<div class="support-layout"><div><p class="support-intro">Elige un módulo individual a S/ 250, dos módulos juntos a S/ 450, tres a S/ 650 o una página completa a S/ 900. También puedes elegir un interior de tapa junto con su solapa.</p><div class="support-options" role="group" aria-label="Seleccionar espacio publicitario">${adOptions.map((o,i)=>`<button class="option ${i===currentAd?'selected':''}" data-ad="${i}" aria-pressed="${i===currentAd}"><span class="radio-mark" aria-hidden="true"></span><span class="option-text"><span class="option-title">${o.title}</span><span class="option-detail">${o.detail}</span></span><span class="option-price ${o.id==='especial'?'price-custom':''}">${o.price}<small>${o.id==='especial'?'según acuerdo':o.id==='individual'?'por espacio':o.id==='dos'||o.id==='tres'?'por paquete':'por espacio'}</small></span></button>`).join('')}</div><p class="selection-note">Cada módulo individual cuesta S/ 250. Los paquetes de dos y tres módulos se ofrecen por S/ 450 y S/ 650, respectivamente; la página completa, por S/ 900. Ubicación, disponibilidad y entrega del arte se coordinan antes de formalizar el acuerdo.</p><button class="button dark support-cta" data-inquire="${a.inquiry}">Consultar este espacio <span>↗</span></button></div><div class="support-visual">${visual}<p class="visual-label">${a.label}</p><p class="visual-note">${a.src?'Modelo compartido de la hoja publicitaria. El ejemplo de anuncio muestra el diseño y no acredita un auspicio confirmado.':'Esquema de ubicación. El arte y las dimensiones se acuerdan con cada aliado.'}</p></div></div>`;
 $$('[data-ad]').forEach(b=>b.addEventListener('click',()=>{currentAd=Number(b.dataset.ad);renderAd();$(`[data-ad="${currentAd}"]`).focus();}));
 $$('[data-open-model]').forEach(b=>b.addEventListener('click',()=>openPage(b.dataset.openModel)));
 bindInquiries($('#support-panel'));
}
function renderSupport(type){
 $$('.support-tabs button').forEach(b=>{const selected=b.dataset.support===type;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;if(selected)$('#support-panel').setAttribute('aria-labelledby',b.id);});
 if(type==='ad'){renderAd();return;}
 if(type==='sponsor'){
  $('#support-panel').innerHTML=`<div class="institution-sponsorship"><div><p class="eyebrow">APOYO A LA CULTURA Y LA MEMORIA</p><h3>Aporte institucional</h3><p>Una contribución para hacer posible la impresión y circulación de Jach’a Puno. Cada institución puede aumentar voluntariamente su aporte según sus posibilidades.</p><p class="selection-note">El reconocimiento institucional y las condiciones de colaboración se coordinan por escrito con el responsable del proyecto.</p></div><div class="institution-amount"><span>Aporte base</span><strong>S/ 1,000</strong><p>Puedes contribuir con un monto mayor.</p><button class="button dark" data-inquire="Aporte institucional (desde S/ 1,000)">Coordinar un aporte <span>↗</span></button></div></div>`;

 }else{
  const options=[{title:'Aporte para impresión',copy:'Contribución parcial al costo de impresión o convenio de cofinanciamiento, con destino y condiciones definidos entre ambas partes.'},{title:'Compra de ejemplares',copy:'Compra anticipada de ejemplares para distribución institucional. Cantidad, precio, entrega y destinos se coordinan según las necesidades de la entidad.'},{title:'Alianza institucional',copy:'Coordinación de acciones de presentación o difusión y reconocimiento institucional, de acuerdo con las políticas de cada entidad.'}];
  $('#support-panel').innerHTML=`<p class="support-intro" style="margin-top:28px">También es posible apoyar la producción o acercar la revista a públicos educativos y culturales mediante una modalidad adaptada a tu institución.</p><div class="institution-options">${options.map((o,i)=>`<article class="institution-card"><span>0${i+1} / APOYO CULTURAL</span><h3>${o.title}</h3><p>${o.copy}</p><button class="text-link" style="background:none;padding-left:0;padding-right:0" data-inquire="${o.title}">Coordinar esta opción <span>↗</span></button></article>`).join('')}</div>`;
 }
 bindInquiries($('#support-panel'));
}
$$('.support-tabs button').forEach(b=>b.addEventListener('click',()=>renderSupport(b.dataset.support)));
keyboardTabs('.support-tabs button',i=>renderSupport($$('.support-tabs button')[i].dataset.support));
function openInquiry(option){$('#inquiry-option').value=option;$('#copy-status').textContent='';openModal($('#inquiry-dialog'));}
function bindInquiries(root=document){$$('[data-inquire]',root).forEach(b=>b.addEventListener('click',()=>openInquiry(b.dataset.inquire)));}
bindInquiries();renderSupport('ad');
function inquiryMessage(){const d=new FormData($('#inquiry-form'));return `Hola, Aldair:\n\nSoy ${d.get('nombre')}${d.get('institucion')?' de '+d.get('institucion'):''}. Nos interesa conocer más sobre la siguiente opción de colaboración con Jach’a Puno:\n\n${d.get('modalidad')}\n\n${d.get('mensaje')||'Agradeceré información sobre disponibilidad, condiciones y próximos pasos.'}\n\nQuedamos atentos para coordinar.\n${d.get('nombre')}\n${d.get('institucion')}`;}
$('#inquiry-form').addEventListener('submit',e=>{e.preventDefault();const body=inquiryMessage();const subject=`Consulta de colaboración · Jach’a Puno · ${new FormData(e.currentTarget).get('institucion')}`;window.location.href=`mailto:espezua.aldair20@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;$('#copy-status').textContent='Consulta preparada. Si no se abre tu correo, puedes copiar el mensaje.';});
$('#copy-inquiry').addEventListener('click',async()=>{if(!$('#inquiry-form').reportValidity())return;try{await navigator.clipboard.writeText(inquiryMessage());$('#copy-status').textContent='Mensaje copiado. Puedes pegarlo en tu correo.';}catch{const t=document.createElement('textarea');t.value=inquiryMessage();t.setAttribute('aria-label','Mensaje para copiar');$('#copy-status').replaceChildren(t);t.select();$('#copy-status').append(document.createTextNode(' Selecciona y copia este mensaje para enviarlo por correo.'));}});

selectSegment(0);

const preOrderForm=$('#preorder-form');
preOrderForm.elements.cantidad.addEventListener('input',()=>{const qty=Number(preOrderForm.elements.cantidad.value);$('.preorder-total').innerHTML=Number.isInteger(qty)&&qty>=1&&qty<=1000?`Total de preventa: <strong>S/ ${qty*25}</strong>`:'Indica una cantidad válida.';});
function prepareContribution(form,preorder){if(!form.reportValidity())return;const d=new FormData(form);const name=String(d.get('nombre')).trim();if(name.split(/\s+/).length<2){form.elements.nombre.setCustomValidity('Escribe tus nombres y apellidos completos.');form.elements.nombre.reportValidity();form.elements.nombre.addEventListener('input',()=>form.elements.nombre.setCustomValidity(''),{once:true});return;}const message=preorder?`Hola, Aldair. Quiero comunicar mi precompra de Jach’a Puno.\n\nNombres completos: ${name}\nCantidad de revistas: ${d.get('cantidad')}\nPrecio por ejemplar: S/ 25\nTotal: S/ ${Number(d.get('cantidad'))*25}\nEntrega: ${d.get('entrega')}\n\nAdjuntaré mi captura de pago de Yape. Conservaré la constancia para reclamar mis ejemplares. Quedo a la espera de la verificación del pago y confirmación.`:`Hola, Aldair. Quiero comunicar mi donación para la impresión de Jach’a Puno.\n\nNombres completos: ${name}\n\nCompartiré los detalles de mi aporte y, si corresponde, la captura de pago en este chat.`;window.open(`https://wa.me/51933927685?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');$('.form-status',form).textContent=preorder?'Mensaje preparado. En WhatsApp, adjunta la captura y envía tus datos. Conserva la captura para recoger tus ejemplares.':'Mensaje preparado. Envía tus datos desde WhatsApp para comunicar tu donación.';}
preOrderForm.addEventListener('submit',e=>{e.preventDefault();prepareContribution(preOrderForm,true);});
$('#donation-form').addEventListener('submit',e=>{e.preventDefault();prepareContribution(e.currentTarget,false);});
